// CD pulse-arc welder firmware model (ESP32-C6-LCD-1.47).
// Senses the bank through the R1-R4 divider (TAP = 2/302 of the bank) and R5,
// and switches the charger's 12 V input with relay K1.
// GPIO1 (ADC) and GPIO19 (K1.IN) are sim-only picks: the real pins are TBD.

fn fmt1(x) {
    let neg = x < 0.0;
    let t = (x.abs() * 10.0).round().to_int();
    let s = `${t / 10}.${t % 10}`;
    if neg { "-" + s } else { s }
}

fn maxf(a, b) { if a > b { a } else { b } }

// Two-point calibration: ADC millivolts -> bank volts, both points read off a meter.
fn bank_volts(mv, k) {
    k.v_lo + (mv - k.mv_lo) * (k.v_hi - k.v_lo) / (k.mv_hi - k.mv_lo)
}

fn state_color(st) {
    switch st {
        "SAFE" => [40, 60, 140],
        "CHARGE" => [200, 130, 0],
        "READY" => [0, 150, 70],
        "HOLD" => [0, 110, 170],
        _ => [200, 0, 0]
    }
}

fn hint(st, fault) {
    switch st {
        "SAFE" => "relay open",
        "CHARGE" => "charging bank...",
        "READY" => "touch pen to work",
        "HOLD" => "welded - lift pen",
        "FAULT" => fault,
        _ => ""
    }
}

fn paint_header(st) {
    let c = state_color(st);
    lcd_rect(0, 0, 128, 18, c[0], c[1], c[2]);
    lcd_text(4, 5, "CD WELDER", 255, 255, 255);
    lcd_text(124 - st.len * 6, 5, st, 255, 255, 255);
}

fn paint_footer(text) {
    lcd_rect(0, 112, 128, 16, 16, 18, 30);
    lcd_text(4, 115, text, 225, 225, 235);
}

fn paint_line(y, text, r, g, b) {
    lcd_rect(0, y - 2, 128, 13, 6, 8, 16);
    lcd_text(4, y, text, r, g, b);
}

fn paint_bar(v, set, full) {
    let w = (v / full * 120.0).to_int();
    if w < 0 { w = 0; }
    if w > 120 { w = 120; }
    lcd_rect(4, 74, 120, 8, 30, 34, 48);
    if w > 0 {
        if v >= set - 4.0 { lcd_rect(4, 74, w, 8, 60, 220, 110); } else { lcd_rect(4, 74, w, 8, 240, 160, 40); }
    }
    let s = (set / full * 120.0).to_int();
    lcd_rect(4 + s, 71, 2, 14, 255, 255, 255);
}

fn on_start() {
    this.k = #{
        adc_pin: 1,          // TBD on hardware (free ADC1 pins: GPIO0-3)
        boot_pin: 9,         // on-board BOOT button cycles the set point
        mv_lo: 0.0,          // calibration point 1: ADC mV ...
        v_lo: 0.0,           // ... and the meter's bank volts
        mv_hi: 1986.8,       // calibration point 2 (ideal 2/302 divider at 300 V)
        v_hi: 300.0,
        presets: [120.0, 180.0, 240.0, 280.0],
        margin_v: 3.0,       // open K1 this far below the set point
        relay_s: 0.010,      // K1 release time added to the loop period
        cutoff_v: 310.0,     // hard cutoff
        timeout_ms: 30000,   // longest charge
        weld_drop_v: 20.0,   // a sample-to-sample drop this big is a weld
        holdoff_ms: 1500,    // K1 stays open after a weld
        topup_v: 8.0,        // recharge when READY sags this far
        stuck_ms: 800,       // charging that cannot pass stuck_v: pen on the work or a short
        stuck_v: 30.0,
        c_f: 0.00019,        // bank capacitance
        boot_ms: 1000,
        full_v: 330.0        // bar-graph full scale (cap rating)
    };
    this.st = "SAFE";
    this.t_state = millis();
    this.preset = 2;
    this.set_v = this.k.presets[2];
    this.v = 0.0;
    this.t_prev = millis();
    this.slope = 0.0;
    this.inc = 0.0;          // last per-sample rise while charging
    this.step = 0.0;         // typical per-sample rise near the set point
    this.welds = 0;
    this.last_j = 0.0;
    this.fault = "";
    this.v_shown = -999.0;
    this.t_paint = 0;
    k1.off();                                   // relay off at boot
    pin(this.k.adc_pin).watch_analog(5);
    pin(this.k.boot_pin).input_pullup();
    lcd_init(6, 7, 14, 15, 21);
    lcd_clear(6, 8, 16);
    paint_header("SAFE");
    paint_line(58, `SET   ${fmt1(this.set_v)} V`, 255, 220, 90);
    paint_line(90, "WELDS 0", 200, 200, 210);
    paint_footer(hint("SAFE", ""));
    rgb(8, 12, 30);
    log("K1 open at boot; charging starts in 1 s. BOOT cycles the set point.");
}

fn on_tick(dt_ms) {
    if this.st == () { return; }
    let k = this.k;
    let now = millis();
    let mv = pin(k.adc_pin).millivolts().to_float();
    let v = bank_volts(mv, k);

    // Fresh samples update the slope; a big drop between samples is a weld.
    let weld = false;
    if v != this.v {
        let dt = (now - this.t_prev).to_float() / 1000.0;
        if this.v - v >= k.weld_drop_v {
            weld = true;
            this.last_j = 0.5 * k.c_f * (this.v * this.v - v * v);
        }
        if dt > 0.0 { this.slope = (v - this.v) / dt; }
        this.inc = maxf(v - this.v, 0.0);
        if this.st == "CHARGE" && v > this.set_v * 0.6 && this.inc > 0.0 { this.step = this.inc; }
        this.v = v;
        this.t_prev = now;
    }

    let st = this.st;
    let next = st;
    let age = now - this.t_state;
    if v > k.cutoff_v {
        next = "FAULT";
        this.fault = "OVER 310 V";
    } else {
        switch st {
            "SAFE" => {
                if age >= k.boot_ms { next = "CHARGE"; }
            },
            "CHARGE" => {
                // Predict where the bank lands once K1 has actually released: half the
                // next sample's rise (the loop's own latency) plus the relay's release time.
                let predicted = v + 0.5 * this.inc + maxf(this.slope, 0.0) * k.relay_s;
                if weld {
                    next = "HOLD";
                } else if predicted >= this.set_v - k.margin_v {
                    next = "READY";
                } else if age > k.timeout_ms {
                    next = "FAULT";
                    this.fault = "CHARGE TIMEOUT";
                } else if age > k.stuck_ms && v < k.stuck_v {
                    next = "FAULT";
                    this.fault = "NO RISE - SHORT?";
                }
            },
            "READY" => {
                if weld {
                    next = "HOLD";
                } else if v < this.set_v - maxf(k.topup_v, this.step) {
                    // Top up only once the bank has sagged by at least one charge step.
                    next = "CHARGE";
                }
            },
            "HOLD" => {
                if age >= k.holdoff_ms { next = "CHARGE"; }
            },
            _ => {}
        }
    }

    if next != st {
        this.st = next;
        this.t_state = now;
        if next == "CHARGE" { k1.on(); } else { k1.off(); }
        let c = state_color(next);
        rgb(c[0] / 5, c[1] / 5, c[2] / 5);
        paint_header(next);
        paint_footer(hint(next, this.fault));
        if next == "HOLD" && weld {
            this.welds += 1;
            paint_line(90, `WELDS ${this.welds}  ${fmt1(this.last_j)} J`, 200, 200, 210);
            log(`weld #${this.welds}: ${fmt1(this.last_j)} J from the bank`);
        }
        if next == "FAULT" { log(`FAULT: ${this.fault} - K1 open`); }
        log(`${st} -> ${next} at ${fmt1(v)} V`);
    }

    if (v - this.v_shown).abs() >= 0.5 && now - this.t_paint >= 60 {
        this.v_shown = v;
        this.t_paint = now;
        let e = 0.5 * k.c_f * v * v;
        paint_line(24, `BANK  ${fmt1(v)} V`, 255, 255, 255);
        paint_line(40, `E     ${fmt1(e)} J`, 170, 200, 255);
        paint_bar(v, this.set_v, k.full_v);
        paint_line(100, `ADC ${mv.to_int()} mV`, 110, 120, 150);
    }
}

// BOOT: clears a fault, otherwise steps through the set-point presets.
fn on_pin(gpio, high) {
    if this.st == () || gpio != this.k.boot_pin || high { return; }
    if this.st == "FAULT" {
        if this.v < this.k.cutoff_v {
            this.st = "SAFE";
            this.t_state = millis();
            this.fault = "";
            k1.off();
            paint_header("SAFE");
            paint_footer(hint("SAFE", ""));
            log("fault cleared");
        }
        return;
    }
    this.preset = (this.preset + 1) % this.k.presets.len();
    this.set_v = this.k.presets[this.preset];
    paint_line(58, `SET   ${fmt1(this.set_v)} V`, 255, 220, 90);
    this.v_shown = -999.0;
    log(`set point ${fmt1(this.set_v)} V`);
}
